<script setup lang="ts">
import { ref } from 'vue';import { useRouter } from 'vue-router';import { useAuthStore } from '../sessionStore'
const email=ref('');const password=ref('');const error=ref('');const busy=ref(false);const auth=useAuthStore();const router=useRouter();async function submit(){busy.value=true;error.value='';try{await auth.login(email.value,password.value);await router.replace('/')}catch(e){error.value=e instanceof Error?e.message:'Unable to sign in.'}finally{busy.value=false}}
</script>
<template><main class="login"><form @submit.prevent="submit"><p class="eyebrow">FULLSTACK STARTER</p><h1>Welcome back</h1><p class="muted">Sign in to continue to the administration workspace.</p><label>Email<input v-model="email" type="email" autocomplete="username" required></label><label>Password<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" class="error">{{error}}</p><button :disabled="busy">{{busy?'Signing in…':'Sign in'}}</button></form></main></template>
<style scoped>.login{min-height:100vh;display:grid;place-items:center;background:#f5f7fa;font-family:Inter,system-ui,sans-serif}form{width:min(390px,calc(100% - 40px));background:white;padding:36px;border:1px solid #e5e7eb;border-radius:14px;box-shadow:0 10px 35px rgba(0,0,0,.05)}.eyebrow{font-size:12px;font-weight:700;letter-spacing:.12em}.muted{color:#6b7280;margin-bottom:28px}label{display:grid;gap:7px;margin:16px 0;font-size:14px;font-weight:600}input{padding:11px 12px;border:1px solid #d1d5db;border-radius:8px;font:inherit}button{width:100%;margin-top:10px;padding:12px;border:0;border-radius:8px;background:#111827;color:white;font-weight:700}.error{color:#b91c1c;font-size:14px}</style>
